# Sample Python Tool
def run(context):
    # Analyze for missing symbol resolutions and suggest fixes
    unresolved_symbols = [entry for entry in context['run_data'] if entry['recommendation'] is None]
    summary_report = {
        'unresolved_count': len(unresolved_symbols),
        'unresolved_symbols': unresolved_symbols
    }
    return summary_report

def run_risk_analysis(portfolio_analysis):
    # Analyze risk based on trading signals and portfolio exposure
    risk_flags = []
    for row in portfolio_analysis:
        if row['trading_signal'] == 'SELL' and row['qty'] > 0:
            risk_flags.append({'symbol': row['symbol'], 'action': 'consider trimming'})
        elif row['trading_signal'] in ('BUY', 'STRONG_BUY') and row['qty'] == 0:
            risk_flags.append({'symbol': row['symbol'], 'action': 'consider adding'})
    return risk_flags

def run(context):
    # Simulate a freshness check on 'run_ts' timestamps
    threshold_date = datetime.now() - relativedelta(months=3)
    data = context['evidence_data']
    fresh_data = [item for item in data if item['run_ts'] >= threshold_date]
    return { 'freshness_report': fresh_data }
